        public static VehicleInfo[] ByCategory(string category)
        {
            var found = new System.Collections.Generic.List<VehicleInfo>();
            for (int i = 0; i < All.Length; i++)
                if (All[i].Category == category) found.Add(All[i]);
            return found.ToArray();
        }

        public static VehicleInfo[] Find(string partial)
        {
            if (string.IsNullOrEmpty(partial)) return new VehicleInfo[0];
            string term = partial.ToLowerInvariant();
            var found = new System.Collections.Generic.List<VehicleInfo>();
            for (int i = 0; i < All.Length; i++)
            {
                VehicleInfo v = All[i];
                if ((v.DisplayName != null && v.DisplayName.ToLowerInvariant().Contains(term)) ||
                    (v.ModelName != null && v.ModelName.ToLowerInvariant().Contains(term)) ||
                    (v.RealName != null && v.RealName.ToLowerInvariant().Contains(term)))
                    found.Add(v);
            }
            return found.ToArray();
        }
    }
